// Incremental PDF patch helper for docr-qt.
//
// Inputs are generated by the C++ exporter:
//   --overlays <manifest>  page index + QPdfWriter overlay PDF, one per page
//   --outline  <manifest>  flattened outline entries, pre-order with depth
//
// The helper imports each overlay page as a Form XObject, appends it to the
// target page, updates the catalog outline, and writes original + delta.

use std::collections::HashMap;
use std::env;
use std::error::Error;
use std::fs;
use std::io::Cursor;
use std::path::{Path, PathBuf};

use pindf::{Dictionary, Document, Modification, Object, Ref, Stream};

const OVERLAY_MAGIC: &[u8; 8] = b"DOCROVL1";
const OUTLINE_MAGIC: &[u8; 8] = b"DOCROUT1";

struct Overlay {
    page: u32,
    path: PathBuf,
}

struct OutlineEntry {
    page: i32,
    level: u32,
    title: String,
}

fn read_u32(cursor: &mut Cursor<Vec<u8>>) -> Result<u32, Box<dyn Error>> {
    let mut bytes = [0u8; 4];
    std::io::Read::read_exact(cursor, &mut bytes)?;
    Ok(u32::from_be_bytes(bytes))
}

fn read_i32(cursor: &mut Cursor<Vec<u8>>) -> Result<i32, Box<dyn Error>> {
    Ok(read_u32(cursor)? as i32)
}

fn read_bytes(cursor: &mut Cursor<Vec<u8>>, len: usize) -> Result<Vec<u8>, Box<dyn Error>> {
    let mut bytes = vec![0u8; len];
    std::io::Read::read_exact(cursor, &mut bytes)?;
    Ok(bytes)
}

fn read_overlays(path: &Path) -> Result<Vec<Overlay>, Box<dyn Error>> {
    let bytes = fs::read(path)?;
    let mut cursor = Cursor::new(bytes);
    let mut magic = [0u8; 8];
    std::io::Read::read_exact(&mut cursor, &mut magic)?;
    if &magic != OVERLAY_MAGIC {
        return Err("bad overlay manifest magic".into());
    }
    let count = read_u32(&mut cursor)? as usize;
    let mut overlays = Vec::with_capacity(count);
    for _ in 0..count {
        let page = read_u32(&mut cursor)?;
        let len = read_u32(&mut cursor)? as usize;
        let raw = read_bytes(&mut cursor, len)?;
        let name = String::from_utf8(raw)?;
        overlays.push(Overlay {
            page,
            path: PathBuf::from(name),
        });
    }
    Ok(overlays)
}

fn read_outline(path: &Path) -> Result<Vec<OutlineEntry>, Box<dyn Error>> {
    let bytes = fs::read(path)?;
    let mut cursor = Cursor::new(bytes);
    let mut magic = [0u8; 8];
    std::io::Read::read_exact(&mut cursor, &mut magic)?;
    if &magic != OUTLINE_MAGIC {
        return Err("bad outline manifest magic".into());
    }
    let count = read_u32(&mut cursor)? as usize;
    let mut entries = Vec::with_capacity(count);
    for _ in 0..count {
        let page = read_i32(&mut cursor)?;
        let level = read_u32(&mut cursor)?;
        let len = read_u32(&mut cursor)? as usize;
        let raw = read_bytes(&mut cursor, len)?;
        entries.push(OutlineEntry {
            page,
            level,
            title: String::from_utf8(raw)?,
        });
    }
    Ok(entries)
}

fn as_dict(obj: &Object) -> Result<Dictionary, Box<dyn Error>> {
    obj.as_dict()
        .cloned()
        .ok_or_else(|| "expected dictionary".into())
}

fn resolve_obj(doc: &mut Document, obj: &Object) -> Result<Object, Box<dyn Error>> {
    if let Some(r) = obj.as_ref() {
        Ok(doc.resolve(r)?.clone())
    } else {
        Ok(obj.clone())
    }
}

fn find_page(
    doc: &mut Document,
    pages: Ref,
    pages_out: &mut Vec<Ref>,
) -> Result<(), Box<dyn Error>> {
    let pages_dict = as_dict(doc.resolve(pages)?)?;
    let kids = pages_dict.get_array("Kids").ok_or("Pages has no Kids")?;
    for kid in kids {
        let Some(reference) = kid.as_ref() else {
            continue;
        };
        let kid_dict = as_dict(doc.resolve(reference)?)?;
        match kid_dict.get_name("Type") {
            Some(b"Page") => pages_out.push(reference),
            Some(b"Pages") => find_page(doc, reference, pages_out)?,
            _ => {}
        }
    }
    Ok(())
}

fn all_pages(doc: &mut Document) -> Result<Vec<Ref>, Box<dyn Error>> {
    let root = doc
        .trailer()
        .get("Root")
        .and_then(Object::as_ref)
        .ok_or("trailer has no Root")?;
    let catalog = as_dict(doc.resolve(root)?)?;
    let pages = catalog
        .get("Pages")
        .and_then(Object::as_ref)
        .ok_or("catalog has no Pages")?;
    let mut result = Vec::new();
    find_page(doc, pages, &mut result)?;
    Ok(result)
}

fn effective_value(
    doc: &mut Document,
    page: &Dictionary,
    key: &str,
) -> Result<Option<Object>, Box<dyn Error>> {
    let mut current = page.clone();
    for _ in 0..64 {
        if let Some(value) = current.get(key) {
            return Ok(Some(resolve_obj(doc, value)?));
        }
        let Some(parent) = current.get("Parent").and_then(Object::as_ref) else {
            break;
        };
        current = as_dict(doc.resolve(parent)?)?;
    }
    Ok(None)
}

fn page_resources(doc: &mut Document, page: &Dictionary) -> Result<Dictionary, Box<dyn Error>> {
    match effective_value(doc, page, "Resources")? {
        Some(value) => as_dict(&value),
        None => Ok(Dictionary::new()),
    }
}

fn content_data(doc: &mut Document, page: &Dictionary) -> Result<Vec<u8>, Box<dyn Error>> {
    let value = page.get("Contents").ok_or("page has no Contents")?;
    let mut out = Vec::new();
    collect_content(doc, value, &mut out)?;
    Ok(out)
}

fn collect_content(
    doc: &mut Document,
    value: &Object,
    out: &mut Vec<u8>,
) -> Result<(), Box<dyn Error>> {
    if let Some(r) = value.as_ref() {
        let resolved = doc.resolve(r)?.clone();
        return collect_content(doc, &resolved, out);
    }
    match value {
        Object::Array(items) => {
            for item in items {
                collect_content(doc, item, out)?;
            }
        }
        Object::Stream(stream) => {
            out.extend_from_slice(&stream.decode()?);
            out.push(b'\n');
        }
        _ => return Err("unsupported Contents value".into()),
    }
    Ok(())
}

fn remap(obj: &Object, map: &HashMap<u32, u32>) -> Result<Object, Box<dyn Error>> {
    Ok(match obj {
        Object::Reference(r) => {
            let num = map.get(&r.num).copied().unwrap_or(r.num);
            Object::Reference(Ref::new(num, r.gen))
        }
        Object::Array(items) => {
            let mut result = Vec::with_capacity(items.len());
            for item in items {
                result.push(remap(item, map)?);
            }
            Object::Array(result)
        }
        Object::Dict(dict) => {
            let mut result = Dictionary::new();
            for (key, value) in dict.iter() {
                result.insert(key, remap(value, map)?);
            }
            Object::Dict(result)
        }
        Object::Stream(stream) => {
            let mut dict = Dictionary::new();
            for (key, value) in stream.dict.iter() {
                dict.insert(key, remap(value, map)?);
            }
            // Streams copied across documents must carry a direct, correct length.
            dict.insert("Length", Object::Int(stream.data.len() as i64));
            Object::Stream(Stream::new(dict, stream.data.clone(), 0))
        }
        other => other.clone(),
    })
}

fn import_overlay(
    overlay_path: &Path,
    next: &mut u32,
    modif: &mut Modification,
) -> Result<(Ref, QRect), Box<dyn Error>> {
    let mut overlay = Document::open(overlay_path)?;
    let max_size = (overlay.xref().size() as u32).max(1);
    let mut map = HashMap::new();
    for old in 1..max_size {
        map.insert(old, *next);
        *next += 1;
    }

    for (&old, &new) in &map {
        if let Ok(object) = overlay.object(old) {
            let copied = remap(object, &map)?;
            modif.add(new, copied);
        }
    }

    let page_refs = all_pages(&mut overlay)?;
    let overlay_page_ref = *page_refs.first().ok_or("overlay has no pages")?;
    let overlay_page = as_dict(overlay.resolve(overlay_page_ref)?)?;
    let data = content_data(&mut overlay, &overlay_page)?;
    let resources = page_resources(&mut overlay, &overlay_page)?;
    let resources = remap(&Object::Dict(resources), &map)?;
    let media = effective_value(&mut overlay, &overlay_page, "MediaBox")?
        .ok_or("overlay page has no MediaBox")?;
    let bbox = media
        .as_array()
        .ok_or("overlay MediaBox is not an array")?
        .to_vec();
    if bbox.len() != 4 {
        return Err("overlay MediaBox must have 4 numbers".into());
    }

    let form_num = *next;
    *next += 1;
    let mut form = Dictionary::new();
    form.insert("Type", Object::name("XObject"));
    form.insert("Subtype", Object::name("Form"));
    form.insert("BBox", Object::Array(bbox.clone()));
    form.insert("Resources", resources);
    form.insert("Length", Object::Int(data.len() as i64));
    modif.add(form_num, Object::Stream(Stream::new(form, data, 0)));

    Ok((Ref::new(form_num, 0), QRect::from_media(&bbox)?))
}

struct QRect {
    width: f64,
    height: f64,
}

impl QRect {
    fn from_media(media: &[Object]) -> Result<Self, Box<dyn Error>> {
        let x0 = number(&media[0])?;
        let y0 = number(&media[1])?;
        let x1 = number(&media[2])?;
        let y1 = number(&media[3])?;
        Ok(Self {
            width: x1 - x0,
            height: y1 - y0,
        })
    }
}

fn number(obj: &Object) -> Result<f64, Box<dyn Error>> {
    match obj {
        Object::Int(v) => Ok(*v as f64),
        Object::Real(v) => Ok(*v),
        _ => Err("expected number".into()),
    }
}

fn page_rotation(doc: &mut Document, page: &Dictionary) -> Result<i32, Box<dyn Error>> {
    let Some(value) = effective_value(doc, page, "Rotate")? else {
        return Ok(0);
    };
    let mut rotation = match value {
        Object::Int(v) => v as i32,
        Object::Real(v) => v as i32,
        _ => 0,
    };
    rotation %= 360;
    if rotation < 0 {
        rotation += 360;
    }
    Ok(rotation)
}

fn attach_overlay(
    doc: &mut Document,
    page_ref: Ref,
    form_ref: Ref,
    form_box: QRect,
    modif: &mut Modification,
    next: &mut u32,
) -> Result<(), Box<dyn Error>> {
    let mut page = as_dict(doc.resolve(page_ref)?)?;
    let rotation = page_rotation(doc, &page)?;
    if rotation != 0 {
        return Err(format!(
            "page {} has /Rotate {rotation}; incremental text layer currently supports 0 only",
            page_ref.num
        )
        .into());
    }

    let mut resources = page_resources(doc, &page)?;
    let mut xobjects = match resources.get("XObject") {
        Some(value) => {
            let resolved = resolve_obj(doc, value)?;
            resolved.as_dict().cloned().unwrap_or_default()
        }
        None => Dictionary::new(),
    };
    let mut name = String::from("DocrText");
    let mut index = 1;
    while xobjects.contains_key(name.as_bytes()) {
        index += 1;
        name = format!("DocrText{index}");
    }
    xobjects.insert(name.as_bytes(), Object::Reference(form_ref));
    resources.insert("XObject", Object::Dict(xobjects));
    page.insert("Resources", Object::Dict(resources));

    let crop = effective_value(doc, &page, "CropBox")?
        .or(effective_value(doc, &page, "MediaBox")?)
        .ok_or("page has no CropBox or MediaBox")?;
    let crop_box = crop.as_array().ok_or("CropBox is not an array")?;
    if crop_box.len() != 4 {
        return Err("CropBox must have 4 numbers".into());
    }
    let x0 = number(&crop_box[0])?;
    let y0 = number(&crop_box[1])?;
    let x1 = number(&crop_box[2])?;
    let y1 = number(&crop_box[3])?;
    let crop_width = x1 - x0;
    let crop_height = y1 - y0;
    let sx = crop_width / form_box.width;
    let sy = crop_height / form_box.height;
    let placement = format!(
        "q\n{:.6} 0 0 {:.6} {:.6} {:.6} cm\n/{} Do\nQ\n",
        sx, sy, x0, y0, name
    );

    let content_num = *next;
    *next += 1;
    let mut content_dict = Dictionary::new();
    content_dict.insert("Length", Object::Int(placement.len() as i64));
    modif.add(
        content_num,
        Object::Stream(Stream::new(content_dict, placement.into_bytes(), 0)),
    );

    let mut contents = Vec::new();
    if let Some(value) = page.get("Contents").cloned() {
        if let Some(reference) = value.as_ref() {
            let resolved = doc.resolve(reference)?.clone();
            if let Object::Array(items) = resolved {
                contents.extend(items);
            } else {
                contents.push(value);
            }
        } else if let Object::Array(items) = value {
            contents.extend(items);
        } else {
            contents.push(value);
        }
    }
    contents.push(Object::Reference(Ref::new(content_num, 0)));
    page.insert("Contents", Object::Array(contents));
    modif.add(page_ref.num, Object::Dict(page));
    Ok(())
}

fn make_text_string(text: &str) -> Object {
    let mut bytes = vec![0xFE, 0xFF];
    for unit in text.encode_utf16() {
        bytes.push((unit >> 8) as u8);
        bytes.push(unit as u8);
    }
    Object::String(bytes)
}

struct OutlineNode {
    page: i32,
    title: String,
    children: Vec<OutlineNode>,
}

fn build_outline_tree(entries: &[OutlineEntry]) -> Vec<OutlineNode> {
    let mut roots: Vec<OutlineNode> = Vec::new();
    let mut stack: Vec<(u32, Vec<usize>)> = Vec::new();
    for entry in entries {
        while stack.last().is_some_and(|(level, _)| *level >= entry.level) {
            stack.pop();
        }
        let node = OutlineNode {
            page: entry.page,
            title: entry.title.clone(),
            children: Vec::new(),
        };
        if stack.is_empty() {
            roots.push(node);
            stack.push((entry.level, vec![roots.len() - 1]));
        } else {
            let mut path = stack.last().unwrap().1.clone();
            let mut parent = &mut roots;
            for index in &path {
                parent = &mut parent[*index].children;
            }
            parent.push(node);
            path.push(parent.len() - 1);
            stack.push((entry.level, path));
        }
    }
    roots
}

struct OutlineLevel {
    first: Ref,
    last: Ref,
    count: i64,
}

fn add_outline_level(
    nodes: &[OutlineNode],
    pages: &[Ref],
    parent: Ref,
    next: &mut u32,
    modif: &mut Modification,
) -> Result<Option<OutlineLevel>, Box<dyn Error>> {
    if nodes.is_empty() {
        return Ok(None);
    }
    let mut refs = Vec::with_capacity(nodes.len());
    for _ in nodes {
        refs.push(Ref::new(*next, 0));
        *next += 1;
    }

    for (index, node) in nodes.iter().enumerate() {
        let mut dict = Dictionary::new();
        dict.insert("Title", make_text_string(&node.title));
        dict.insert("Parent", Object::Reference(parent));
        if node.page >= 0 && (node.page as usize) < pages.len() {
            dict.insert(
                "Dest",
                Object::Array(vec![
                    Object::Reference(pages[node.page as usize]),
                    Object::name("Fit"),
                ]),
            );
        }
        if index > 0 {
            dict.insert("Prev", Object::Reference(refs[index - 1]));
        }
        if index + 1 < refs.len() {
            dict.insert("Next", Object::Reference(refs[index + 1]));
        }
        modif.add(refs[index].num, Object::Dict(dict));
    }

    let mut total = nodes.len() as i64;
    for (index, node) in nodes.iter().enumerate() {
        if node.children.is_empty() {
            continue;
        }
        let child = add_outline_level(&node.children, pages, refs[index], next, modif)?
            .ok_or("outline child level unexpectedly empty")?;
        let node_object = modif.get(refs[index].num).unwrap().object.clone();
        let mut dict = as_dict(&node_object)?;
        dict.insert("First", Object::Reference(child.first));
        dict.insert("Last", Object::Reference(child.last));
        dict.insert("Count", Object::Int(child.count));
        modif.add(refs[index].num, Object::Dict(dict));
        total += child.count;
    }

    Ok(Some(OutlineLevel {
        first: refs[0],
        last: *refs.last().unwrap(),
        count: total,
    }))
}

fn add_outline(
    doc: &mut Document,
    entries: &[OutlineEntry],
    pages: &[Ref],
    next: &mut u32,
    modif: &mut Modification,
) -> Result<(), Box<dyn Error>> {
    if entries.is_empty() {
        return Ok(());
    }
    let roots = build_outline_tree(entries);
    if roots.is_empty() {
        return Ok(());
    }

    let root_ref = Ref::new(*next, 0);
    *next += 1;
    let mut root = Dictionary::new();
    root.insert("Type", Object::name("Outlines"));

    let level = add_outline_level(&roots, pages, root_ref, next, modif)?
        .ok_or("outline tree unexpectedly empty")?;
    root.insert("First", Object::Reference(level.first));
    root.insert("Last", Object::Reference(level.last));
    root.insert("Count", Object::Int(level.count));
    modif.add(root_ref.num, Object::Dict(root));

    let root_page_ref = doc
        .trailer()
        .get("Root")
        .and_then(Object::as_ref)
        .ok_or("trailer has no Root")?;
    let mut catalog = as_dict(doc.resolve(root_page_ref)?)?;
    catalog.insert("Outlines", Object::Reference(root_ref));
    catalog.insert("PageMode", Object::name("UseOutlines"));
    modif.add(root_page_ref.num, Object::Dict(catalog));
    Ok(())
}

fn run(args: &[String]) -> Result<(), Box<dyn Error>> {
    let mut input = None;
    let mut output = None;
    let mut overlays_path = None;
    let mut outline_path = None;
    let mut index = 1;
    while index < args.len() {
        let key = args[index].as_str();
        let value = args.get(index + 1).ok_or("missing option value")?;
        match key {
            "--input" => input = Some(PathBuf::from(value)),
            "--output" => output = Some(PathBuf::from(value)),
            "--overlays" => overlays_path = Some(PathBuf::from(value)),
            "--outline" => outline_path = Some(PathBuf::from(value)),
            _ => return Err(format!("unknown option {key}").into()),
        }
        index += 2;
    }
    let input = input.ok_or("missing --input")?;
    let output = output.ok_or("missing --output")?;
    let overlays_path = overlays_path.ok_or("missing --overlays")?;
    let outline_path = outline_path.ok_or("missing --outline")?;
    if input == output {
        return Err("input and output must differ".into());
    }

    let overlays = read_overlays(&overlays_path)?;
    let outline = read_outline(&outline_path)?;
    let mut doc = Document::open(&input)?;
    if doc.is_encrypted() {
        return Err("encrypted PDFs are not supported".into());
    }
    let pages = all_pages(&mut doc)?;
    let mut next = (doc.xref().size() as u32)
        .max(doc.modification().max_obj_num().unwrap_or(0) + 1)
        .max(1);
    let mut modif = Modification::new();

    for overlay in overlays {
        if overlay.page as usize >= pages.len() {
            return Err(format!("overlay page {} is out of range", overlay.page).into());
        }
        let (form_ref, form_box) = import_overlay(&overlay.path, &mut next, &mut modif)?;
        // pindf borrows doc mutably while importing; attach afterwards.
        attach_overlay(
            &mut doc,
            pages[overlay.page as usize],
            form_ref,
            form_box,
            &mut modif,
            &mut next,
        )?;
    }

    add_outline(&mut doc, &outline, &pages, &mut next, &mut modif)?;
    doc.set_modification(modif);
    doc.save(&output)?;
    Ok(())
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if let Err(error) = run(&args) {
        eprintln!("pindf-append: {error}");
        std::process::exit(1);
    }
}
